const sessionEntrySnapshotColumnsDefinition=[[`sessionDiffBaseline`,`session_diff_baseline_json`],[`skillsSnapshot`,`skills_snapshot_json`],[`systemPromptReport`,`system_prompt_report_json`]];function attachSessionEntrySnapshots(e,t,n=`full`){for(const[r,i]of sessionEntrySnapshotColumnsDefinition){if(n!==`full`&&(n===`list`||!n.includes(r))){Reflect.deleteProperty(e,r);continue}const a=t[i];if(a!=null){const t=JSON.parse(a);Object.assign(e,{[r]:t})}}return e}export{sessionEntrySnapshotColumnsDefinition as n,attachSessionEntrySnapshots as t};